            b[row][0] = value;
            b[row][m - 1] = value;
            return b;
        }

        // n 是偶数，m 是奇数，只能使用大小为 2 的上下对称轨道
        if (n % 2 == 0 && m % 2 == 1) {
            if (totalSum % 2 != 0) {
                return null;
            }
            long value = totalSum / 2;
            int col = m / 2;
            b[0][col] = value;
            b[n - 1][col] = value;
            return b;
        }

        // n 和 m 都是偶数，所有对称轨道大小都是 4
        if (totalSum % 4 != 0) {
            return null;
        }
        long value = totalSum / 4;
        b[0][0] = value;
        b[0][m - 1] = value;
        b[n - 1][0] = value;
        b[n - 1][m - 1] = value;
        return b;
    }

    public static void main(String[] args) throws Exception {
        BufferedInputStream in = new BufferedInputStream(System.in);
