            int n = nextInt(in);
            int m = nextInt(in);

            // 读取原矩阵时只需要求元素总和
            long totalSum = 0;
            for (int i = 0; i < n * m; i++) {
                totalSum += nextLong(in);
            }

            long[][] b = buildMatrix(n, m, totalSum);

            // 无法构造时输出 -1
