    vector<vector<long long>> b(n, vector<long long>(m, 0));
    ok = true;

    // n 和 m 都是奇数，中心格子单独对称，可以放任意总和
    if (n % 2 == 1 && m % 2 == 1) {
        b[n / 2][m / 2] = totalSum;
        return b;
    }

    // n 是奇数，m 是偶数，只能使用大小为 2 的左右对称轨道
    if (n % 2 == 1 && m % 2 == 0) {
        if (totalSum % 2 != 0) {
            ok = false;
            return b;
        }
        long long value = totalSum / 2;
        int row = n / 2;
        b[row][0] = value;
        b[row][m - 1] = value;
        return b;
    }

    // n 是偶数，m 是奇数，只能使用大小为 2 的上下对称轨道
    if (n % 2 == 0 && m % 2 == 1) {
        if (totalSum % 2 != 0) {
            ok = false;
            return b;
        }
        long long value = totalSum / 2;
        int col = m / 2;
        b[0][col] = value;
        b[n - 1][col] = value;
        return b;
    }

    // n 和 m 都是偶数，所有对称轨道大小都是 4
    if (totalSum % 4 != 0) {
        ok = false;
        return b;
    }
    long long value = totalSum / 4;
    b[0][0] = value;
    b[0][m - 1] = value;
    b[n - 1][0] = value;
    b[n - 1][m - 1] = value;
    return b;
}

